SET semester = 3
WHERE id = 'b4eeaef2-6d11-422b-b5a3-d5844e695476';

-- 2. Reset syllabus topic completion states for the 4 batch courses to be imported
UPDATE public.uct_batch_course_syllabus
SET is_completed = false, completed_date = null
WHERE batch_course_id IN (
  'dc4d7721-01df-4b96-b67e-6626d3242f7f', -- MIM-BBA-2024-28 DADSUS
